"""RegimeContext — shared context object injected into every agent."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path

import pandas as pd

_ROOT = Path(__file__).resolve().parent.parent

# Was a hand-maintained dict, regenerated by hand after every run_regime.py refit
# (label semantics are NOT stable across refits — went stale on 2026-07-14, and again
# during the 2026-07-20 covariance-regularization refit before this fix). Now generated
# dynamically from data/validated/regime_semantics.json, the same fix already applied to
# dashboard/backend/regime_service.py._load_regime_descriptions() — one source of truth,
# can't go stale by forgetting a manual edit. Cached per-process; call
# invalidate_regime_descriptions_cache() after regenerating regime_semantics.json within
# a running process (e.g. the dashboard backend).
_descriptions_cache: dict[str, dict[int, str]] = {}
_stats_cache: dict[str, dict[int, dict]] = {}

_DEFAULT_SEMANTICS_PATH = _ROOT / "data" / "validated" / "regime_semantics.json"


def _load_regime_stats(semantics_path: Path | None = None) -> dict[int, dict]:
    """Raw per-regime financial stats (sharpe, realized_vol_mean, annualized_return, ...)
    loaded from a regime_semantics.json-style file — {"regimes": {"0": {...}, "1": {...}}}.

    semantics_path is opt-in (2026-08-14) — None resolves to production's
    data/validated/regime_semantics.json, preserving exact prior behavior for every
    existing caller. Pass an explicit path (e.g. data/validated/btc_only_v3_regime_
    semantics.json) to classify regimes from a different HMM's stream — see
    classify_regime_volatility_level and classify_regime_volatility_trend, shared by
    this module's descriptions AND agents/fund_manager.py's conviction logic, so both
    always agree with whatever regime_semantics.json actually says instead of a
    hardcoded per-index table.
    Cached per (resolved path); call invalidate_regime_descriptions_cache() after
    regenerating a semantics file within a running process.
    """
    path = semantics_path or _DEFAULT_SEMANTICS_PATH
    key = str(path)
    if key in _stats_cache:
        return _stats_cache[key]

    if not path.exists():
        _stats_cache[key] = {}
        return {}
    try:
        sem = json.loads(path.read_text())
    except Exception:
        _stats_cache[key] = {}
        return {}

    stats = {int(label): s for label, s in sem.get("regimes", {}).items()}
    _stats_cache[key] = stats
    return stats


def classify_regime_volatility_level(stats: dict) -> str:
    """Bucket a regime's raw stats into a volatility-magnitude category for conviction
    sizing — replaces the former sharpe-sign-based classify_regime_kind() (removed
    2026-09-01). That function bucketed regimes as bull/bear/crash from sharpe sign and
    fed agents/fund_manager.py's conviction multipliers and directional override sets.
    An objective zigzag trend-leg test (regime/validate_regime_trend_alignment.py, 111
    legs across all 5 crypto5 assets, 2021) found only 49% of legs had a dominant regime
    whose historical sharpe sign matched the leg's actual price direction — statistically
    a coin flip — and the regime nominally labeled "strong bull" (crypto5's R4) was
    dominant on MORE down-legs than up-legs (40.6% up). Sharpe sign is a population
    average over the regime's full history, not a reliable per-instance directional
    signal, so it cannot honestly drive a directional trading override.

    realized_vol_mean is direction-agnostic by construction and is the dimension that
    actually held up under validation (this project's regime-distinctness testing
    consistently finds volatility clusters, not directional ones). Using it for
    conviction sizing only (scale confidence down when volatility/uncertainty is
    elevated, symmetrically for bullish and bearish calls) is a defensible risk-
    management principle that does not require — and does not claim — knowledge of
    which direction the regime favors.

    Returns one of: "extreme_vol", "elevated_vol", "normal_vol" (also the fallback for
    missing data, since "assume normal" is the safe default when nothing is known).
    """
    if not stats:
        return "normal_vol"
    rvol = float(stats.get("realized_vol_mean", 0.0))
    if rvol > 1.5:
        return "extreme_vol"
    elif rvol > 0.5:
        return "elevated_vol"
    else:
        return "normal_vol"


def classify_regime_volatility_trend(stats: dict) -> str:
    """Bucket a regime's raw stats into a volatility/trend-strength descriptor —
    deliberately NOT a bull/bear label. Unlike sharpe, realized_vol_mean and adx_mean
    don't encode a direction claim at all (ADX is trend STRENGTH regardless of sign in
    classic TA), and this is the dimension that actually held up under validation — see
    classify_regime_volatility_level's docstring for the zigzag test that found
    sharpe-derived direction labels wrong more often than not at the per-instance level.
    """
    if not stats:
        return "unknown"
    rvol = float(stats.get("realized_vol_mean", 0.0))
    adx = float(stats.get("adx_mean", 0.0))

    if rvol > 1.5:
        vol = "extreme volatility"
    elif rvol > 0.5:
        vol = "elevated volatility"
    elif rvol > -0.3:
        vol = "moderate volatility"
    elif rvol > -0.9:
        vol = "low volatility"
    else:
        vol = "very low volatility"

    trend = "trending" if adx >= 0 else "range-bound"
    return f"{vol}, {trend}"


def _load_regime_descriptions(semantics_path: Path | None = None) -> dict[int, str]:
    path = semantics_path or _DEFAULT_SEMANTICS_PATH
    key = str(path)
    if key in _descriptions_cache:
        return _descriptions_cache[key]

    stats_by_label = _load_regime_stats(semantics_path)
    if not stats_by_label:
        _descriptions_cache[key] = {}
        return {}

    descriptions: dict[int, str] = {}
    for label, stats in stats_by_label.items():
        ann_return = float(stats.get("annualized_return", 0.0))
        ann_vol = float(stats.get("annualized_vol", 0.0))
        sharpe = float(stats.get("sharpe", 0.0))
        time_pct = float(stats.get("time_pct", 0.0))
        dom = str(stats.get("dominant_asset", ""))
        vol_trend = classify_regime_volatility_trend(stats)

        descriptions[label] = (
            f"{vol_trend.capitalize()} — {dom}-dominant, {time_pct:.1%} of time. "
            f"Historical ann. return {ann_return:+.1%}, ann. vol {ann_vol:.1%}, Sharpe "
            f"{sharpe:.2f} (population average, not a reliable per-instance directional "
            f"signal — see classify_regime_volatility_trend)"
        )

    _descriptions_cache[key] = descriptions
    return descriptions


def invalidate_regime_descriptions_cache() -> None:
    """Call after regime_semantics.json is regenerated so the next lookup re-reads it."""
    global _descriptions_cache, _stats_cache
    _descriptions_cache = {}
    _stats_cache = {}

_WINDOW_INDICATORS = ["realized_vol", "rsi", "adx", "close_return"]

USE_PER_ASSET_REGIME: bool = False
# 2026-07-14: reverted to False (documented default per run_per_asset_regime.py's own
# "Consequence" note). Was found flipped to True while pointing at
# data/processed/regime_stream_per_asset.parquet, which is stale (predates the
# 2026-07-14 walk-forward encoder retrain by 10 days) — every BTC_USDT debate was
# silently being built against a two-generations-old regime map. All debates use the
# shared regime_stream.parquet (freshly refit) unless this is deliberately re-enabled
# after regenerating the per-asset stream on the current encoder.
# Example structure: {0: 'BTC calm/transitional', 1: 'BTC calm bull', 2: 'BTC crash/crisis', ...}
_BTC_REGIME_DESCRIPTIONS: dict[int, str] = {
    0: "BTC bear/crisis — strong downtrend (ann. return -189.5%), elevated volatility, "
       "worst risk-adjusted performance (Sharpe -2.77), trending (ADX+)",
    1: "BTC calm/range-bound — mild positive drift (ann. return +15.7%), moderate volatility, "
       "near-neutral risk-adjusted return (Sharpe 0.23)",
    2: "BTC high-volatility/transitional — near-zero net return (ann. +0.4%) despite the "
       "highest raw volatility band, non-trending (ADX-), choppy price action; this is the "
       "regime BTC's March 2020 crash occurs within (pre-crash and crash windows both fall "
       "in R2, distinguished by a sharp internal probability shift rather than a label change)",
    3: "BTC volatile bull — strong uptrend (ann. return +94.9%) with high realized volatility, "
       "trending (ADX+), solid risk-adjusted return (Sharpe 0.98)",
    4: "BTC calm bull — strongest uptrend (ann. return +203.5%) combined with the lowest "
       "volatility of any BTC regime, best risk-adjusted performance (Sharpe 3.36)",
}
_PER_ASSET_STREAM_PATH = _ROOT / 'data' / 'processed' / 'regime_stream_per_asset.parquet'
_per_asset_stream_cache: dict[str, pd.DataFrame] = {}


def _resolve_regime_stream(regime_stream_df: pd.DataFrame, asset: str) -> pd.DataFrame:
    """Return per-asset stream only for BTC when USE_PER_ASSET_REGIME is True."""
    if not USE_PER_ASSET_REGIME or asset != "BTC_USDT":
        return regime_stream_df
    if "data" not in _per_asset_stream_cache:
        if _PER_ASSET_STREAM_PATH.exists():
            _per_asset_stream_cache["data"] = pd.read_parquet(
                _PER_ASSET_STREAM_PATH, engine="pyarrow"
            )
        else:
            return regime_stream_df
    return _per_asset_stream_cache["data"]



@dataclass
class RegimeContext:
    timestamp: pd.Timestamp
    asset: str
    regime_label: int
    regime_probs: dict[str, float]
    dominant_regime: int
    regime_description: str
    price_features: dict[str, float]
    window_features: dict[str, float]
    live_headlines: list | None = None  # injected by dashboard live mode
    upcoming_events: list | None = None  # injected by dashboard live mode — see
    # pipeline/live/economic_calendar.get_upcoming_events(). None in historical/replay
    # debates (a past debate can't know the future's economic calendar).
    regime_stale: bool = False  # True when build_regime_context() couldn't find an exact
    # timestamp match in the regime stream and fell back to the nearest available row —
    # found 2026-08-18 during the LLM layer audit: this fallback was previously silent,
    # serving a regime row up to tens of hours old with no signal to the agent or the
    # prompt. Never raises (a hard failure would take down live debates on any ordinary
    # data gap) — surfaced as an explicit flag instead, both in the prompt text
    # (serialize_context_for_prompt) and in this dataclass for programmatic checks.
    regime_gap_hours: float = 0.0  # |requested timestamp - resolved regime row timestamp|


def build_regime_context(
    timestamp: pd.Timestamp,
    asset: str,
    regime_stream_df: pd.DataFrame,
    aligned_df: pd.DataFrame,
    semantics_path: Path | None = None,
) -> RegimeContext:
    """Build RegimeContext for a given timestamp and asset.

    semantics_path is opt-in (2026-08-14) — None resolves to production's
    data/validated/regime_semantics.json (exact prior behavior). Pass an explicit path
    when regime_stream_df comes from a different HMM (e.g. the BTC-only-v3 encoder's),
    so ctx.regime_description matches the regime stream actually being described instead
    of silently describing a different HMM's regimes. Found 2026-08-14: without this,
    a BTC-only regime stream's context showed production's "ETH_USDT-dominant" text for
    a regime that, for BTC-only-v3, is 100% BTC_USDT by construction — same staleness
    class as FundManagerAgent's now-fixed regime-stats lookup (agents/fund_manager.py)."""
    ts_utc = pd.Timestamp(timestamp).tz_convert("UTC") if pd.Timestamp(timestamp).tzinfo else pd.Timestamp(timestamp).tz_localize("UTC")

    # Resolve aligned index timezone
    aligned_tz = aligned_df.index.tz
    if aligned_tz is not None:
        ts_aligned = ts_utc.tz_convert(aligned_tz)
    else:
        ts_aligned = ts_utc.tz_localize(None)

    # Look up regime row
    active_stream = _resolve_regime_stream(regime_stream_df, asset)
    mask = (active_stream["asset"] == asset) & (active_stream["timestamp"] == ts_utc)
    regime_rows = active_stream[mask]
    regime_stale = False
    regime_gap_hours = 0.0
    if regime_rows.empty:
        # Fall back to nearest available timestamp. get_indexer(method="nearest") requires
        # a uniquely-valued index — regime_stream_per_asset.parquet has one duplicated
        # BTC_USDT timestamp (a boundary artifact from however the file was built), which
        # makes pandas treat the *whole* index as non-unique and raise InvalidIndexError
        # for every nearest-lookup, not just ones near that specific timestamp. This is
        # the path a live "now" request always takes once it's past the data's end date.
        asset_df = active_stream[active_stream["asset"] == asset].copy()
        asset_df = asset_df.set_index("timestamp").sort_index()
        asset_df = asset_df[~asset_df.index.duplicated(keep="last")]
        idx = asset_df.index.get_indexer([ts_utc], method="nearest")[0]
        row = asset_df.iloc[idx]
        resolved_ts = asset_df.index[idx]
        regime_gap_hours = abs((ts_utc - resolved_ts).total_seconds()) / 3600.0
        regime_stale = regime_gap_hours > 1.0  # >1 candle away from the requested bar
    else:
        row = regime_rows.iloc[0]

    regime_label = int(row["regime_label"])
    prob_cols = [c for c in active_stream.columns if c.startswith("regime_prob_")]
    regime_probs = {col.replace("regime_prob_", "regime_"): float(row[col]) for col in prob_cols}
    dominant_regime = max(regime_probs, key=regime_probs.get)
    dominant_regime_int = int(dominant_regime.replace("regime_", ""))

    # Extract 13 features at the timestamp
    if ts_aligned in aligned_df.index:
        feature_row = aligned_df.loc[ts_aligned]
    else:
        idx = aligned_df.index.get_indexer([ts_aligned], method="nearest")[0]
        feature_row = aligned_df.iloc[idx]
    price_features = {col: float(feature_row[col]) for col in aligned_df.columns}

    # 60-candle window stats
    aligned_sorted = aligned_df.sort_index()
    loc = aligned_sorted.index.get_indexer([ts_aligned], method="pad")[0]
    start = max(0, loc - 59)
    window = aligned_sorted.iloc[start : loc + 1]
    window_features: dict[str, float] = {}
    for ind in _WINDOW_INDICATORS:
        if ind in window.columns:
            window_features[f"{ind}_mean"] = float(window[ind].mean())
            window_features[f"{ind}_std"] = float(window[ind].std(ddof=1) if len(window) > 1 else 0.0)

    return RegimeContext(
        timestamp=ts_utc,
        asset=asset,
        regime_label=regime_label,
        regime_probs=regime_probs,
        dominant_regime=dominant_regime_int,
        regime_description=(
            _BTC_REGIME_DESCRIPTIONS.get(regime_label)
            if USE_PER_ASSET_REGIME
            and asset == "BTC_USDT"
            and regime_label in _BTC_REGIME_DESCRIPTIONS
            else _load_regime_descriptions(semantics_path).get(regime_label, "Unknown regime")
        ),
        price_features=price_features,
        window_features=window_features,
        regime_stale=regime_stale,
        regime_gap_hours=round(regime_gap_hours, 2),
    )


def serialize_context_for_prompt(ctx: RegimeContext, include_regime: bool = True) -> str:
    """Serialize RegimeContext into a compact prompt-ready string (<400 tokens).

    ``include_regime=False`` drops the regime label, regime description, and probability
    vector entirely — used to run "clean" no-regime-context ablation debates (see
    ``run_clean_ablation_debates.py``). Price features and window stats are unaffected.
    """
    price_lines = "\n".join(
        f"  {k}: {v:.4f}" for k, v in list(ctx.price_features.items())[:8]
    )

    window_lines = "\n".join(
        f"  {k}: {v:.4f}" for k, v in ctx.window_features.items()
    )

    events_block = _serialize_upcoming_events(ctx.upcoming_events)

    if not include_regime:
        return (
            f"Asset: {ctx.asset} | Timestamp: {ctx.timestamp}\n\n"
            f"=== PRICE FEATURES (latest) ===\n{price_lines}\n\n"
            f"=== MARKET CHARACTER (60-candle window) ===\n{window_lines}\n"
            f"{events_block}"
        )

    probs_str = ", ".join(
        f"R{k.split('_')[-1]}={v:.2f}" for k, v in sorted(ctx.regime_probs.items()) if v > 0.01
    )

    staleness_line = (
        f"⚠ REGIME DATA STALE — nearest available row is {ctx.regime_gap_hours:.1f}h from "
        f"the current timestamp, not exact. Weight this regime signal accordingly.\n"
        if ctx.regime_stale else ""
    )

    return (
        f"=== REGIME STATE ===\n"
        f"Asset: {ctx.asset} | Timestamp: {ctx.timestamp}\n"
        f"{staleness_line}"
        f"Regime: R{ctx.regime_label} — {ctx.regime_description}\n"
        f"Regime probabilities: {probs_str}\n\n"
        f"=== PRICE FEATURES (latest) ===\n{price_lines}\n\n"
        f"=== MARKET CHARACTER (60-candle window) ===\n{window_lines}\n"
        f"{events_block}"
    )


def _serialize_upcoming_events(events: list | None) -> str:
    """Compact block for upcoming economic-calendar events (dashboard live mode only —
    see RegimeContext.upcoming_events). Empty string when there are none, so historical
    replay debates and quiet stretches don't grow the prompt for nothing."""
    if not events:
        return ""

    def _line(e: dict) -> str:
        base = f"  {e['hours_until']:+.1f}h | {e['currency']} | {e['impact'].upper()} | {e['title']}"
        fcst, prev = e.get("forecast"), e.get("previous")
        if fcst or prev:
            base += f" | fcst={fcst} prev={prev}"
        return base

    lines = "\n".join(_line(e) for e in events[:8])  # cap prompt growth — soonest-first
    return f"\n=== UPCOMING ECONOMIC EVENTS ===\n{lines}\n"
